(1189, NULL, 'CONSTELLATION', 'NS45', 'Aerojac', '{"grupo":"CONSTELLATION","unidade":"NS45","data":"2026-09-13","local":"Aerojac","modal":"Helicóptero","preposto":"Luan Martins","observacao_nome_arquivo":"TRANSFERIDO","horarios":{"saida_hotel":[{"label1":"Previsto","h1":"04","m1":"20","label2":"Real","h2":"04","m2":"30"}],"embarque_previsto":"06:39","embarque_real":"00:00","atendimento_inicio":"03:30","atendimento_fim":"15:00"},"info_troca":"Voo foi postergado para a tarde, mas transferido por motivo de condições meteorológicas&nbsp;","pax_embarcando":"01 CLAUDIOMAR MENDES CORDEIRO\n02 DARLAN DOS SANTOS MOTA\n03 DURVAL SILVA MACEDO\n04 GABRIEL FERREIRA DA SILVA\n05 GABRIEL PAIVA DE ALMEIDA\n06 GUILHERME CKAYAN SOARES DA SILVEIRA\n07 KIRKIS DOUGLAS LUCIO VIANA\n08 MAURO CEZAR LOBO MOTA\n09 PAULO JUNIOR SANTOS RIBEIRO\n10 WAGNER LANNES ARANHA**\n","pax_desembarcando":"N.A","fotos":[]}', 0, NULL, '2026-09-15 11:05:00', '2026-09-15 11:05:03', 'TECHNIP', NULL, 'relatorios_pdf/6aa9265f242f6_NS45_13-09-2026_(06h39)_TRANSFERIDO.pdf', '2804:14d:5cc7:5592:1b34:c2a8:db3e:921');
